def solve():
    try:
        input_data = sys.stdin.read().split()
    except Exception:
        return

    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))
    except StopIteration:
        return

    # Memoization dictionary: key is a tuple representing the current subarray slice
    # However, since we always split from the original array, we can just use (start, end) indices
    memo = {}

    def is_sorted(arr):
        for i in range(len(arr) - 1):
            if arr[i] > arr[i+1]:
                return False
        return True

    def get_max_sorted_length(start, end):
        # Base case: empty or single element is always sorted
        if end - start <= 1:
            return end - start

        state = (start, end)
        if state in memo:
            return memo[state]

        # Check if current slice is already sorted
        current_slice = a[start:end]
        if is_sorted(current_slice):
            memo[state] = end - start
            return end - start

        # If not sorted, we must snap: remove first half or second half
        mid = (start + end) // 2

        # Option 1: Keep the first half [start, mid)
        left_len = get_max_sorted_length(start, mid)

        # Option 2: Keep the second half [mid, end)
        right_len = get_max_sorted_length(mid, end)

        result = max(left_len, right_len)
        memo[state] = result
        return result

    result = get_max_sorted_length(0, n)
    print(result)

